// Package postgres implements the bot domain's stores against
// PostgreSQL via jackc/pgx. The queries are generated by sqlc from
// queries.sql.
package postgres

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
	"github.com/garamsh/garam/platform/internal/app"
	"github.com/garamsh/garam/platform/internal/bot"
	"github.com/garamsh/garam/platform/internal/bot/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
)

// Store implements what is declared on an instance, what it reports
// and the tokens its connector exchanges for its bots.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time checks that Store satisfies the stores.
var (
	_ bot.DeclarationStore = (*Store)(nil)
	_ bot.ReportStore      = (*Store)(nil)
	_ bot.BotTokenStore    = (*Store)(nil)
)

// New constructs a Postgres-backed store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// inTx runs fn in one transaction that holds g's row first and hands fn
// the database's time, and commits what fn wrote. An instance no row
// holds is missing.
func (s *Store) inTx(ctx context.Context, g grn.GRN, missing error, fn func(q *db.Queries, now time.Time) error) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)
	decided, err := q.HoldInstance(ctx, g.String())
	if err != nil {
		return pgxerr.Classify(err, "hold instance", missing, nil)
	}
	if err := fn(q, decided.Time.UTC()); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return errorx.Wrap(err, "commit", errorx.KindUnavailable)
	}
	return nil
}

// storedGRN parses an instance's GRN the database holds, which its
// constraints already admitted, so a failure is the database's fault.
func storedGRN(s string) (grn.GRN, error) {
	g, err := grn.Parse(s)
	if err != nil || !app.IsInstanceGRN(g) {
		return grn.GRN{}, errorx.New(errorx.KindInternal, "stored instance grn "+s+" is not an instance's")
	}
	return g, nil
}
